BEGIN;
CREATE TEMP TABLE branding_results(result jsonb);
ALTER TABLE pg_temp.branding_results ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE a uuid; b uuid; u uuid; m uuid; other uuid; rec uuid; wallet uuid; q jsonb; denied boolean; plan text; checks int:=0;
BEGIN
 FOREACH plan IN ARRAY ARRAY['BASIC','PRO','ENTERPRISE'] LOOP
  a:=gen_random_uuid();b:=gen_random_uuid();
  INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES(a,'branding-admin-'||a||'@example.invalid',now(),'{}'),(b,'branding-reader-'||b||'@example.invalid',now(),'{}');
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);u:=mp_private.actor();
  INSERT INTO public."Mosque"(name,slug,status) VALUES('Branding rollback fixture',gen_random_uuid()::text,'ACTIVE') RETURNING id INTO m;
  INSERT INTO public."Mosque"(name,slug,status) VALUES('Other branding fixture',gen_random_uuid()::text,'ACTIVE') RETURNING id INTO other;
  INSERT INTO public."MosqueSettings"("mosqueId",plan,data) VALUES(m,plan,'{"name":"Branding fixture","timezone":"Asia/Jakarta","email":"PRIVATE_EMAIL"}');
  INSERT INTO public."MosqueMembership"("mosqueId","userId",status) VALUES(m,u,'ACTIVE');INSERT INTO public."MosqueAdmin"("mosqueId","userId") VALUES(m,u);
  IF public.mp_mosque_logo(m) IS NOT NULL THEN RAISE EXCEPTION 'missing_logo_no_fallback'; END IF;checks:=checks+1;
  q:=public.mp_save_record(m,'rekening','{"type":"Bank","provider":"Bank Fixture","number":"0012 3456 7890","holder":"Masjid Fixture","purpose":"Donasi"}');rec:=(q->'record'->>'id')::uuid;
  IF q->'record'->'data'->>'number'<>'0012 3456 7890' THEN RAISE EXCEPTION 'leading_zero_lost'; END IF;checks:=checks+1;
  q:=public.mp_save_record(m,'rekening','{"type":"E-wallet","provider":"Wallet Fixture","number":"081234567890","holder":"Masjid Fixture","purpose":"Infaq & Shodaqoh"}');wallet:=(q->'record'->>'id')::uuid;checks:=checks+1;
  q:=public.mp_set_mosque_logo(m,'fixture_logo_photo_id');
  IF q->'settings'->>'timezone'<>'Asia/Jakarta' OR (SELECT s.plan FROM public."MosqueSettings" s WHERE s."mosqueId"=m)<>plan THEN RAISE EXCEPTION 'logo_clobbered_settings'; END IF;checks:=checks+1;
  IF public.mp_mosque_logo(m)<>'fixture_logo_photo_id' OR public.mp_mosque_logo(other) IS NOT NULL THEN RAISE EXCEPTION 'logo_tenant_scope'; END IF;checks:=checks+1;
  q:=public.mp_save_record(m,'profil','{"name":"Updated fixture","city":"Jakarta","address":"Alamat Masjid fixture","vision":"Untuk Pelayanan Umat Yang Lebih Baik."}');
  IF q->'settings'->>'logoPhotoId'<>'fixture_logo_photo_id' THEN RAISE EXCEPTION 'profile_lost_logo'; END IF;checks:=checks+1;
  q:=public.mp_save_record(m,'rekening','{"type":"Bank","provider":"Bank Baru Fixture","number":"00999999999","holder":"Masjid Fixture"}',rec);
  IF q->'record'->'data'->>'provider'<>'Bank Baru Fixture' THEN RAISE EXCEPTION 'account_edit'; END IF;checks:=checks+1;
  PERFORM public.mp_save_record(m,'infaq','{"receipt":"Infaq","form":"Uang","date":"2026-10-26","amount":"1000","source":"Takmir Masjid"}');checks:=checks+1;
  PERFORM public.mp_save_record(m,'infaq','{"receipt":"Shodaqoh","form":"Uang","date":"2026-10-26","amount":"1000","source":"Aplikasi"}');checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_save_record(m,'rekening','{"type":"Bank","provider":"Fixture","number":"javascript:alert(1)","holder":"Fixture"}');EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'invalid_account_allowed'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_set_mosque_logo(m,'https://example.invalid/image.png');EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'invalid_logo_allowed'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_set_mosque_logo(other,'fixture_other_photo');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'cross_tenant_logo_write'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_save_record(other,'rekening','{}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'cross_tenant_account_write'; END IF;checks:=checks+1;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
  denied:=false;BEGIN PERFORM public.mp_set_mosque_logo(m,'fixture_reader_photo');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'reader_logo_write'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_save_record(m,'rekening','{}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'reader_account_write'; END IF;checks:=checks+1;
  PERFORM set_config('request.jwt.claims','{}',true);
  q:=public.mp_public_workspace(m);
  IF q->'settings'->>'vision'<>'Untuk Pelayanan Umat Yang Lebih Baik.' THEN RAISE EXCEPTION 'public_vision_missing'; END IF;checks:=checks+1;
  IF q::text LIKE '%PRIVATE_%' OR (q->>'canWrite')::boolean OR jsonb_array_length(jsonb_path_query_array(q,'$.records[*] ? (@.kind == "rekening")'))<>2 THEN RAISE EXCEPTION 'public_account_projection'; END IF;checks:=checks+1;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q->'records') x WHERE x->>'id'=rec::text AND x->'data'->>'number'='00999999999' AND x->'data'->>'holder'='Masjid Fixture') THEN RAISE EXCEPTION 'public_account_fields'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_set_mosque_logo(m,'fixture_anonymous_photo');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'anonymous_logo_write'; END IF;checks:=checks+1;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
  PERFORM public.mp_archive_record(m,rec);q:=public.mp_public_workspace(m);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(q->'records') x WHERE x->>'id'=rec::text) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q->'records') x WHERE x->>'id'=wallet::text) THEN RAISE EXCEPTION 'account_archive'; END IF;checks:=checks+1;
  UPDATE public."Mosque" SET status='SUSPENDED',"archivedAt"=now() WHERE id=m;
  IF public.mp_mosque_logo(m) IS NOT NULL THEN RAISE EXCEPTION 'suspended_logo_exposed'; END IF;checks:=checks+1;
  denied:=false;BEGIN PERFORM public.mp_public_workspace(m);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'suspended_accounts_exposed'; END IF;checks:=checks+1;
 END LOOP;
 IF has_function_privilege('anon','public.mp_set_mosque_logo(uuid,text)','EXECUTE') OR NOT has_function_privilege('anon','public.mp_mosque_logo(uuid)','EXECUTE') OR has_table_privilege('anon','public."MosqueSettings"','UPDATE') THEN RAISE EXCEPTION 'unsafe_logo_grants'; END IF;checks:=checks+1;
 INSERT INTO branding_results VALUES(jsonb_build_object('result','PASS','plans',3,'checks',checks));
END $$;
SELECT * FROM branding_results;
ROLLBACK;
